from collections import deque
from string import ascii_lowercase


class Solution:
    def ladderLength(self, beginWord: str, endWord: str, wordList: list[str]) -> int:
        words = set(wordList)
        if endWord not in words:
            return 0
        queue = deque([beginWord])
        seen = {beginWord}
        steps = 1                                   # chain length counts words, so start at 1
        while queue:
            for _ in range(len(queue)):             # one BFS level
                word = queue.popleft()
                if word == endWord:
                    return steps
                for i in range(len(word)):          # L positions
                    for ch in ascii_lowercase:      # 26 letters -> 26 * L candidates, each built in O(L)
                        nxt = word[:i] + ch + word[i + 1:]
                        if nxt in words and nxt not in seen:
                            seen.add(nxt)           # mark on enqueue: each word enters the queue once
                            queue.append(nxt)
            steps += 1
        return 0
